<template><div class="app-container"><div class="filter-container"><el-select v-model="query.roleCode" clearable placeholder="收益身份" class="filter-item"><el-option v-for="item in roleOptions" :key="item.roleCode" :label="item.roleName" :value="item.roleCode" /></el-select><el-select v-model="query.userId" filterable remote clearable placeholder="选择用户" :remote-method="searchUsers" :loading="userLoading" class="filter-item user-filter"><el-option v-for="user in userOptions" :key="user.id" :label="user.label" :value="user.id" /></el-select><el-button type="primary" @click="load">查询</el-button></div><el-table v-loading="loading" :data="list" border><el-table-column prop="accountNo" label="账户号" min-width="165" /><el-table-column label="用户" min-width="180"><template slot-scope="{row}"><div>{{ row.applicantName || '用户不存在' }}</div><div class="sub-text">{{ row.userNickname || '--' }} / {{ row.applicantPhone || '--' }}</div></template></el-table-column><el-table-column label="身份" width="140"><template slot-scope="{row}"><div>{{ row.roleName || '身份未配置' }}</div><div class="sub-text">{{ row.regionName || '区域未配置' }}</div></template></el-table-column><el-table-column prop="availableAmount" label="可提现" width="110" /><el-table-column prop="withdrawingAmount" label="提现中" width="110" /><el-table-column prop="withdrawnAmount" label="已提现" width="110" /><el-table-column prop="frozenAmount" label="冻结资金" width="110" /><el-table-column prop="negativeOffsetAmount" label="待抵扣" width="100" /><el-table-column label="状态" width="90"><template slot-scope="{row}"><el-tag size="mini" :type="row.statusTag || 'info'">{{ row.statusText || (row.status?'启用':'停用') }}</el-tag></template></el-table-column></el-table></div></template>
<script>import { getJkBusinessRoleList, getJkFundAccountList } from '@/api/jkBusiness'
import { userListApi } from '@/api/user'; export default { data() { return { query: { roleCode: '', userId: '' }, list: [], loading: false, roleOptions: [], userOptions: [], userLoading: false } }, created() { this.loadRoles(); this.load() }, methods: { loadRoles() { getJkBusinessRoleList({ page: 1, limit: 100, enabled: true }).then(res => { this.roleOptions = res.data || res || [] }) }, searchUsers(keyword) { if (!keyword || !keyword.trim()) { this.userOptions = []; return } this.userLoading = true; userListApi({ keywords: keyword, page: 1, limit: 20 }).then(response => { const users = response.list || response.data || []; this.userOptions = users.map(user => ({ id: user.uid || user.id, label: (user.nickname || user.realName || '用户') + '（' + (user.uid || user.id) + '）' })) }).finally(() => { this.userLoading = false }) }, load() { this.loading = true; getJkFundAccountList(this.query).then(response => { this.list = response.data || response || [] }).finally(() => { this.loading = false }) } }}; </script>
<style scoped>.filter-item{width:150px;margin-right:8px}.user-filter{width:130px}.sub-text{font-size:12px;color:#909399}</style>
